    // Unmanaged buffers and cached Font instances intentionally live for the process lifetime.
    private static readonly List<IntPtr> Buffers = new();
    private static readonly Dictionary<string, Font> Cache = new();
    private static readonly FontFamily RegularFamily = Load(RegularCollection, RegularData, "Segoe UI");
    private static readonly FontFamily StrongFamily = Load(StrongCollection, StrongData, "Segoe UI Semibold");
    private static FontFamily Load(PrivateFontCollection collection, string encoded, string fallback)
    {
        try
        {
            using var packed = new MemoryStream(Convert.FromBase64String(encoded));
            using var zip = new GZipStream(packed, CompressionMode.Decompress);
            using var decoded = new MemoryStream(); zip.CopyTo(decoded);
            byte[] bytes = decoded.ToArray();
            IntPtr memory = Marshal.AllocCoTaskMem(bytes.Length); Marshal.Copy(bytes, 0, memory, bytes.Length); Buffers.Add(memory);
            uint count = 0; AddFontMemResourceEx(memory, (uint)bytes.Length, IntPtr.Zero, ref count);
            collection.AddMemoryFont(memory, bytes.Length);
            return collection.Families[0];
        }
        catch { return new FontFamily(fallback); }
    }
    public static Font Get(float pixels, bool strong = false)
    {
        string key = pixels.ToString(System.Globalization.CultureInfo.InvariantCulture) + (strong ? "s" : "r");
        lock (Cache)
        {
            if (!Cache.TryGetValue(key, out var font))
                Cache[key] = font = new Font(strong ? StrongFamily : RegularFamily, pixels, FontStyle.Regular, GraphicsUnit.Pixel);
            return font;
        }
    }
